package org.slavicmyths.morozko;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.InteractionResult;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.Level;
public final class TrialTotem extends Item {
 public TrialTotem(){super(new Properties().stacksTo(1).rarity(Rarity.RARE));}
 @Override public InteractionResult useOn(UseOnContext c){if(!(c.getPlayer() instanceof ServerPlayer p))return InteractionResult.sidedSuccess(c.getLevel().isClientSide);var w=p.serverLevel();var d=FrostLedger.get(w);var n=d.player(p.getUUID());String reason=null;if(w.dimension()!=Level.OVERWORLD)reason="overworld";else if(!p.isCreative()&&d.now(w)<n.getLong("TrialReady"))reason="wait";else if(!w.getEntitiesOfClass(Morozko.class,p.getBoundingBox().inflate(120),b->!(b instanceof IceDouble)&&b.session!=null&&b.anchor.distanceToSqr(p.position())<=6400).isEmpty())reason="active";else if(!w.mayInteract(p,c.getClickedPos())||p.server.isUnderSpawnProtection(w,c.getClickedPos(),p))reason="space";else if(!w.getBlockState(c.getClickedPos()).isFaceSturdy(w,c.getClickedPos(),c.getClickedFace()))reason="space";
 if(reason!=null){p.displayClientMessage(FrostContent.text(reason),true);return InteractionResult.FAIL;}
 var aim=p.position().add(p.getLookAngle().multiply(1,0,1).normalize().scale(8));var at=FrostWorld.safe(w,aim,1.35f,4,3);if(at==null||!w.mayInteract(p,net.minecraft.core.BlockPos.containing(at))||p.server.isUnderSpawnProtection(w,net.minecraft.core.BlockPos.containing(at),p)){p.displayClientMessage(FrostContent.text("space"),true);return InteractionResult.FAIL;}var boss=FrostContent.BOSS.get().create(w);if(boss==null)return InteractionResult.FAIL;boss.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(FrostConfig.health());boss.setHealth(FrostConfig.health());boss.session=java.util.UUID.randomUUID();boss.owner=p.getUUID();boss.anchor=p.position();boss.setPos(at);var s=d.session(boss.session);s.putUUID("Boss",boss.getUUID());s.putUUID("Owner",p.getUUID());s.putLong("Anchor",p.blockPosition().asLong());s.putString("Dimension",w.dimension().location().toString());s.putLong("Started",d.now(w));n.putLong("TrialReady",d.now(w)+FrostRules.TRIAL_CD);d.setDirty();if(!w.addFreshEntity(boss)){s.putBoolean("Cancelled",true);n.putLong("TrialReady",0);d.setDirty();p.displayClientMessage(FrostContent.text("space"),true);return InteractionResult.FAIL;}FrostContent.sound(boss,"trial_call");p.sendSystemMessage(FrostContent.text("start"));org.slavicmyths.tales.TaleService.promote(p,"slavicmyths:morozko_trial",3,false);return InteractionResult.CONSUME;}
 @Override public void appendHoverText(ItemStack s,TooltipContext c,java.util.List<net.minecraft.network.chat.Component> l,TooltipFlag f){l.add(FrostContent.text("totem_hint"));}
}
